B.a3f=new A.ad(983167,"MaterialIcons",null,!1)
B.NA=new A.eM(B.a3f,"Phone as a sensor device","Use the phone running the app as a local sensor source for supported motion data workflows.")
B.Nz=new A.eM(B.iS,"Configurable local sensors","Phone sensor streams support configurable sampling options and start with sampling disabled until selected.")
B.a8K=s([B.Ny,B.NO,B.NB,B.NA,B.Nz],t.Fv)
B.NS=new A.lZ("1.2.0","OpenWearables 1.2.0","Automate OpenWearables\nwith the new connector","Control the app over WebSocket and use your phone as a sensor source.","OpenWearables now includes a connector that exposes app control through a WebSocket API. The Python API builds on that connection, making scripted workflows, external tools, and repeatable automation possible.",B.a8K)
B.NI=new A.eM(B.qA,"Audio recorder","Record microphone audio directly from the app as part of a local recording session.")
B.NP=new A.eM(B.z1,"Live waveform monitoring","Preview incoming audio levels before and during capture to verify the selected input.")
B.a36=new A.ad(63511,"MaterialIcons",null,!0)
